# outdoor (template adapted: place instead of room)
def outdoor(room,ground,key,small):
    p=fill(room,ground,'nothing','{K}')
    p=p.replace('of a natural, lived-in, richly furnished room','of a natural, real outdoor place').replace('same depth with furniture, curtains and objects arranged through the whole room from the foreground to the back','same depth with trees, buildings, plants and objects arranged through the whole scene from the foreground to the back')
    p=p.replace('FLOOR: '+ground+' visible between the furniture, no large rug or carpet covering the floor (at most a small mat under nothing); {K} sits','GROUND: '+ground+'; '+key+' sits')
    p=p.replace('Do not leave the room empty like a stage; it should feel natural and furnished','Do not leave the place empty like a stage; it should feel natural and full of detail').replace('the left part of the room near the viewer','the left part of the scene near the viewer').replace('so a person standing in the room','so a person standing there')
    p=p.replace('ROOM: ','PLACE: ',1)
    p=p.replace(' Empty of people',f' In the left foreground there is only open {ground.split(",")[0]}, with at most {small}; no big plant, rock, tree trunk or wall there. Empty of people')
    return p
